   173  file_prepare_stream(const char *fname, uint len, const char *file_access,
   174                   uint buffer_size, stream ** ps, char fmode[4], gs_memory_t *mem)
   175  {
   176      byte *buffer;
   177      register stream *s;
   178
   179      /* Open the file, always in binary mode. */
   180      strcpy(fmode, file_access);
   181      strcat(fmode, gp_fmode_binary_suffix);
   182      if (buffer_size == 0)
   183          buffer_size = file_default_buffer_size;
   184      if (len >= buffer_size)    /* we copy the file name into the buffer */
   185          return_error(gs_error_limitcheck);
   186      /* Allocate the stream first, since it persists */
   187      /* even after the file has been closed. */
   188      s = file_alloc_stream(mem, "file_prepare_stream");
   189      if (s == 0)
   190          return_error(gs_error_VMerror);
   191      /* Allocate the buffer. */
   192      buffer = gs_alloc_bytes(mem, buffer_size, "file_prepare_stream(buffer)");
   193      if (buffer == 0) {
   194          gs_free_object(mem, s, "file_prepare_stream");
   195          return_error(gs_error_VMerror);
   196      }
   197      if (fname != 0) {
   198          memcpy(buffer, fname, len);
   199          buffer[len] = 0;        /* terminate string */
   200      } else
   201          buffer[0] = 0;  /* safety */
   202      s->cbuf = buffer;
   203      s->bsize = s->cbsize = buffer_size;
   204      s->save_close = 0;      /* in case this stream gets disabled before init finishes */
   205      *ps = s;
   206      return 0;
   207  }
   186  ssetfilename(stream *s, const byte *data, uint size)
   187  {
   188      byte *str =
   189          (s->file_name.data == 0 ?
   190           gs_alloc_string(s->memory, size + 1, "ssetfilename") :
   191           gs_resize_string(s->memory,
   192                            (byte *)s->file_name.data,    /* break const */
   193                            s->file_name.size,
   194                            size + 1, "ssetfilename"));
   195
   196      if (str == 0)
   197          return -1;
   198      memcpy(str, data, size);
   199      str[size] = 0;
   200      s->file_name.data = str;
   201      s->file_name.size = size + 1;
   202      return 0;
   203  }
